-- Schema migrations and DDL as run by migration tools
CREATE TABLE users (id NUMBER(38,0) NOT NULL, email VARCHAR(255) NOT NULL, first_name VARCHAR, created_at TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), CONSTRAINT pk_users PRIMARY KEY (id), CONSTRAINT uq_users_email UNIQUE (email));
CREATE TABLE IF NOT EXISTS orders (id NUMBER AUTOINCREMENT START 1 INCREMENT 1, user_id NUMBER NOT NULL, total NUMBER(12,2), status VARCHAR(20) DEFAULT 'pending', placed_at TIMESTAMP_TZ, FOREIGN KEY (user_id) REFERENCES users (id));
CREATE OR REPLACE TABLE events (event_id VARCHAR, payload VARIANT, tags ARRAY, props OBJECT, event_ts TIMESTAMP_LTZ) CLUSTER BY (event_ts);
CREATE TRANSIENT TABLE staging_events (raw VARIANT);
CREATE TEMPORARY TABLE tmp_ids (id NUMBER);
CREATE TABLE sales_clone CLONE sales;
CREATE OR REPLACE TABLE sales_backup CLONE sales AT (TIMESTAMP => '2024-05-01 00:00:00'::timestamp_ltz);
CREATE TABLE sales_before CLONE sales BEFORE (STATEMENT => '8e5d0ca9-005e-44e6-b858-a8f5b37c5726');
CREATE TABLE order_summary AS SELECT user_id, COUNT(*) AS n, SUM(total) AS total FROM orders GROUP BY user_id;
CREATE OR REPLACE TABLE dim_date AS SELECT DATEADD(day, SEQ4(), '2020-01-01'::date) AS d FROM TABLE(GENERATOR(ROWCOUNT => 3650));
CREATE TABLE like_users LIKE users;
CREATE OR REPLACE VIEW v_active_users AS SELECT id, email FROM users WHERE deleted_at IS NULL;
CREATE OR REPLACE SECURE VIEW v_orders_secure AS SELECT id, user_id, total FROM orders;
CREATE MATERIALIZED VIEW mv_daily_sales AS SELECT order_date, SUM(total) AS total FROM orders GROUP BY order_date;
CREATE VIEW v_with_cols (a, b) AS SELECT 1, 2;
ALTER TABLE users ADD COLUMN phone VARCHAR(32);
ALTER TABLE users ADD COLUMN IF NOT EXISTS locale VARCHAR(10) DEFAULT 'en';
ALTER TABLE users DROP COLUMN phone;
ALTER TABLE users RENAME COLUMN first_name TO given_name;
ALTER TABLE users RENAME TO app_users;
ALTER TABLE orders ALTER COLUMN id SET DEFAULT order_seq.NEXTVAL;
ALTER TABLE orders ALTER COLUMN total SET NOT NULL;
ALTER TABLE orders ALTER COLUMN total DROP NOT NULL;
ALTER TABLE orders ADD CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users (id);
ALTER TABLE events CLUSTER BY (event_ts, event_id);
ALTER TABLE events SET DATA_RETENTION_TIME_IN_DAYS = 7;
ALTER TABLE sales SWAP WITH sales_clone;
DROP TABLE IF EXISTS tmp_ids;
DROP VIEW IF EXISTS v_active_users;
DROP TABLE users CASCADE;
UNDROP TABLE users;
CREATE SCHEMA IF NOT EXISTS analytics;
CREATE DATABASE dev_db CLONE prod_db;
CREATE OR REPLACE SEQUENCE order_seq START = 1 INCREMENT = 1;
CREATE FILE FORMAT my_csv TYPE = 'CSV' FIELD_DELIMITER = ',' SKIP_HEADER = 1;
CREATE STAGE my_stage URL = 's3://bucket/path/' FILE_FORMAT = (TYPE = 'PARQUET');
COMMENT ON TABLE users IS 'Application users';
